insert into insights (title, body, position) values
  ('Frictionless Matchday ist das größte Anstoß-Feld.', 'Digitale Tickets (#27, Score 4,25), Mobile Order & In-Seat (#24) und Cashless (#26) liegen in Europa im Anstoß. FC Bayern verkauft ab 2026/27 nur noch digitale Tickets, der VfB Stuttgart setzt mit der LBBW mobile Kartenterminals ein.', 0),
  ('US-Tempo ist kein Europa-Tempo.', 'Fünf Trends werden in Europa anders eingeordnet als global: Biometrischer Zugang (#18) und Bar- & Küchenrobotik (#10) rutschen ins Scouting, Checkout-freie Gastronomie (#19) und Dynamic Pricing (#12) ins Aufwärmen. Treiber sind DSGVO, EU AI Act und Fankultur.', 1),
  ('Schanktechnik wird zum Umsatzhebel.', 'Self-Pour-Bierwände laufen mit Sodexo Live! beim Millwall FC erstmals dauerhaft in Europa; 2026 wurde ein Schanksystem im Honda Center als beste neue Technologie ausgezeichnet (#25).', 2),
  ('Automatisierung beginnt bei der Planung, nicht beim Roboter.', 'KI-Absatzplanung im Catering (#11) ist reif und in DACH verfügbar, etwa mit Delicious Data aus München. Roboter in Küche, Bar und Service (#9, #10) bleiben in Europa im Scouting.', 3),
  ('Premium trägt das Ergebnis.', 'Premium-Hospitality-Tiers (#13) haben mit 4,50 den höchsten Score; verbunden mit Hotel und Anreise (#16) entsteht das stärkste Produkt an der Schnittstelle von Venue und Hotellerie.', 4),
  ('KI-Agenten verändern den Hotelvertrieb.', 'Marriott-Buchungen sollen direkt in Google AI Mode laufen; Apaleo bindet KI-Agenten per MCP-Server an Hotelsysteme an (#6). Die Schnittstellen müssen jetzt entstehen, auch wenn der Trend noch im Aufwärmen liegt.', 5),
  ('Sicherheit wird datengetrieben.', 'DFB und DFL testeten 2025/26 acht Piloten an zwölf Standorten, darunter KI-Crowd-Management und Wetterberatung (#37, #41). KI-Screening (#38) und Drohnenabwehr (#39) sind in Deutschland rechtlich und organisatorisch eng begrenzt.', 6),
  ('Teilhabe ist das Gegengewicht zu Premium.', 'Faire Preise & Teilhabe (#44) steht in Europa im Anstoß: Die Premier League verlängert die 30-£-Obergrenze für Auswärtstickets. Der European Accessibility Act (#42) und Sensory Rooms (#43) machen Inklusion zur Pflicht und zum Profil.', 7),
  ('Energie wird eigene Infrastrukturaufgabe.', 'Speicher und Energiemanagement (#34) glätten Lastspitzen an Eventtagen; die Johan Cruijff ArenA nutzt 3 MW aus wiederverwendeten E-Auto-Batterien. Holz- und Modularbau (#36) bleibt eine langfristige Option.', 8),
  ('Fan Engagement bündelt sich in einer Plattform.', 'Club-Superapps (#4) vereinen Ticket, Bezahlen und Loyalty; KI-Fan-Assistenten (#5) sind früh und in der Qualität noch schwankend. Fan Tokens (#17) bleiben im Scouting.', 9);
