insert into trends (number, name, cluster_code, focus_code, subtopic_id, origin, description, use_cases, best_practice, signals_summary, opportunities, risks, evidence, uncertain, mandatory, status) values
  (1, 'Hyper-Personalisierung', 'A', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Plattformen'), 'EU', 'KI steuert Angebote, Inhalte und Services entlang der gesamten Gast- und Fan-Journey individuell – vom Ticketkauf bis zum Hotelzimmer.', 'Personalisierte Matchday-Journey in der Club-App; Upgrade-Angebote nach Präferenzprofil; individuelle Konzert-Pakete.', 'DFL/Bundesliga mit AWS als GenAI-Partner für personalisierte Inhalte [s13, s14].', 'Belegt: DFL baut KI-Partnerschaft mit AWS aus. Prognose: Personalisierung wird Standarderwartung.', 'Höhere Conversion, Warenkorb und Wiederkehr.', 'DSGVO, Datensilos, Filterblasen-Effekt.', 'A', false, false, 'published'),
  (2, 'Loyalty-Ökosysteme', 'A', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Loyalty'), 'GLOBAL', 'Branchenübergreifende Treueprogramme verbinden Stadion, Hotel, Mobilität und Entertainment in einer Währung.', 'Punkte aus Hotelaufenthalten für Matchday-Erlebnisse einlösen; Status-Stufen über Partner hinweg.', 'Wissensbasis: Hotel-Loyalty-Programme mit Event-Erlebnissen als Prämie (z. B. Marriott Bonvoy Moments) – im Detail zu validieren.', 'Prognose: Loyalty wird zum Datenrückgrat für Personalisierung und Agentic Booking.', 'Höherer Customer Lifetime Value, Partner-Erlöse.', 'Komplexe Abrechnung, Programmmüdigkeit.', 'B', false, false, 'published'),
  (3, 'Gamifizierte Second Screens', 'A', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Gamification'), 'EU', 'Interaktive Live-Daten, Prognosespiele und Echtzeit-Statistiken binden Fans vor Ort und zu Hause.', 'Live-Predictions in der App, Match-Facts-Overlays, Belohnungen für Teilnahme.', 'Bundesliga Match Facts auf Basis der AWS-Partnerschaft [s13].', 'Belegt: datengetriebene Fan-Features im Ligabetrieb.', 'Mehr Nutzungszeit und Sponsoring-Inventar.', 'Nähe zu Glücksspiel, Ablenkung vom Live-Erlebnis.', 'B', false, false, 'published'),
  (4, 'Club-Superapps', 'A', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Plattformen'), 'EU', 'Eine App bündelt Ticket, Einlass, Bezahlen, Bestellen, Content und Loyalty – statt vieler Einzel-Apps.', 'Digitales Ticket mit Wallet, In-Seat-Bestellung, Mitgliederstatus und Live-Daten in einer Oberfläche.', 'FC Bayern stellt ab 2026/27 auf rein digitale Tickets in der App um, inkl. Wallet und Zweitmarkt [s74]; Vitória SC baut mit Blocksport eine Fan-Superapp [s92].', 'Belegt: Clubs bündeln Funktionen in eigenen Apps. Offen: Fans ohne Smartphone.', 'Datenhoheit, höhere Nutzungsfrequenz, Grundlage für Personalisierung.', 'Entwicklungskosten, Ausschluss von Fans ohne Smartphone, App-Müdigkeit.', 'A', false, false, 'published'),
  (5, 'KI-Fan-Assistenten', 'A', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Plattformen'), 'GLOBAL', 'Sprach- und Chat-Assistenten beantworten Fragen zu Ticket, Anreise, Stadion und Club rund um die Uhr.', 'Matchday-Fragen (Einlass, Parken, Barrierefreiheit), Ticket-Support, personalisierte Club-Inhalte.', 'Infobip startet den KI-Fan-Companion PitchMate [s93]; die Premier League testet einen KI-Companion, der in Tests noch schwach abschneidet [s94].', 'Belegt: erste Produkte am Markt. Unsicher: Qualität und Mehrwert.', 'Entlastung des Service, Datengewinn, 24/7-Erreichbarkeit.', 'Falschauskünfte, Markenrisiko, Datenschutz.', 'A', false, false, 'published'),
  (6, 'Agentic Booking', 'B', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Hotellerie'), 'GLOBAL', 'KI-Agenten recherchieren, kombinieren und buchen Tickets, Hotel und Anreise selbstständig im Auftrag des Gastes.', 'Agent bucht Matchday-Paket inkl. Hotel; automatische Umbuchung bei Spielverlegung.', 'Marriott: Google AI Mode soll Hotelbuchungen direkt abwickeln [s27]; Bericht: KI-Agenten beginnen Hotelzimmer zu buchen [s29].', 'Belegt: erste agentische Buchungen. Prognose: KI konsolidiert Hotelsuche und -buchung bis 2035 [s28].', 'Neue Vertriebskanäle, Paketierung in Echtzeit.', 'Disintermediation, Verlust des Kundenkontakts, Plattformabhängigkeit.', 'A', false, false, 'published'),
  (7, 'GenAI-Content-Automation', 'B', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Content & Community'), 'EU', 'Generative KI erstellt Highlights, Zusammenfassungen und mehrsprachige Inhalte in Echtzeit.', 'Automatische Clips je Spieler; mehrsprachige Spielberichte; personalisierte Konzert-Recaps.', 'WSC Sports erstellt KI-Highlights für BVB, DFB-Pokal und Red Bull München [s62, s63, s64]; Bundesliga nutzt Amazon Nova [s14].', 'Belegt: Produktivbetrieb in der Bundesliga.', 'Mehr Reichweite bei geringeren Produktionskosten.', 'Rechtefragen, Qualitäts- und Markenrisiken.', 'A', false, false, 'published'),
  (8, 'Venue Digital Twins', 'B', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Stadionbau'), 'GLOBAL', 'Virtuelle Echtzeit-Abbilder von Venues für Planung, Betrieb, Energie und Vermarktung.', 'Event-Szenarien simulieren; Sponsoring-Sichtbarkeit planen; Energieverbrauch optimieren.', 'Anbieter-Lösungen für Stadion-Digital-Twins [s35].', 'Belegt: Anbieterangebote. Prognose: Standard bei Neubauten.', 'Effizienz im Betrieb, neue Planungsservices für Veranstalter.', 'Hohe Integrationskosten, BIM-Datenlage.', 'C', true, false, 'published'),
  (9, 'Service-Robotik', 'B', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Robotik'), 'GLOBAL', 'Roboter übernehmen Lieferung, Reinigung und einfache Gästeservices in Venues und Hotels.', 'Lieferroboter im Hotel; Reinigungsroboter nach Events.', 'Wissensbasis: Erfahrungen mit Roboter-Hotels zeigen begrenzte Akzeptanz – zu validieren.', 'Prognose: Fachkräftemangel erhöht Druck; Reife für Gästeinteraktion gering.', 'Entlastung bei Personalmangel.', 'Akzeptanz, Wartung, Wirtschaftlichkeit.', 'C', true, false, 'published'),
  (10, 'Bar- & Küchenrobotik', 'B', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Robotik'), 'US', 'Roboter übernehmen standardisierte Schritte in Küche und Bar, etwa Frittieren, Zapfen oder Cocktails.', 'Frittierstationen in Stadionküchen, Getränkeroboter in Fan-Zonen und Arenen.', 'Pilot des Küchenroboters Flippy (Miso Robotics) mit Caterer Levy im Dodger Stadium [s83].', 'Belegt: Piloten seit 2018. Unsicher: Skalierung in Europa, Wirtschaftlichkeit bei wenigen Spieltagen.', 'Entlastung bei Personalmangel, konstante Qualität in Spitzenzeiten.', 'Auslastung nur an Eventtagen, Wartung, Hygienezulassung.', 'B', true, false, 'published'),
  (11, 'KI-Gastroplanung', 'B', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Kiosk & Gastro'), 'EU', 'KI prognostiziert Absatz je Kiosk und Spieltag und steuert Einkauf, Produktion und Personal.', 'Mengenplanung nach Gegner, Wetter, Anstoßzeit; Personalplanung; weniger Food Waste.', 'Delicious Data aus München liefert KI-Absatzprognosen für Gastronomie und Catering und sammelte frisches Kapital ein [s84].', 'Belegt: Lösungen am Markt in DACH. Prognose: Standard bei Großcaterern.', 'Weniger Abfall, höhere Marge, weniger Ausverkauf.', 'Datenqualität der Kassen, Integration beim Caterer.', 'B', false, false, 'published'),
  (12, 'Fair Dynamic Pricing', 'C', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'VIP & Premium'), 'US', 'Preise passen sich Nachfrage an – mit Transparenz- und Fairnessregeln, um Vertrauen zu sichern.', 'Nachfragebasierte Preise für Tagestickets und Hotelzimmer; Preisgarantie für Mitglieder.', 'CMA-Fall Oasis: keine dynamische Preisgestaltung nachgewiesen, Ticketmaster ändert UK-Verkauf [s15]; Hotelpreise steigen bei Großevents [s31].', 'Belegt: regulatorischer Druck in UK. Prognose: Transparenzpflichten nehmen zu.', 'Ertragsoptimierung, weniger Zweitmarkt.', 'Fan-Backlash, Regulierung, Reputationsschaden.', 'A', false, false, 'published'),
  (13, 'Premium-Hospitality-Tiers', 'C', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'VIP & Premium'), 'GLOBAL', 'Ausdifferenzierte VIP-Stufen vom Social Club bis zur Suite steigern den Erlös pro Platz.', 'Tunnel-Club-Formate, Field-Level-Lounges, Konzert-Premium-Pakete.', 'FC Barcelona: neues VIP-Sitzmodell im Spotify Camp Nou [s46]; Las Vegas Grand Prix mit fast 220 Mio. US$ Hotelzimmerumsatz [s45].', 'Belegt: Clubs und Promoter erhöhen Premium-Anteil.', 'Höchster Erlös pro Quadratmeter.', 'Exklusionswirkung, Fan-Kultur-Konflikte.', 'A', false, false, 'published'),
  (14, 'Experience-Abos', 'C', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Loyalty'), 'GLOBAL', 'Mitgliedschaften bündeln Zugang, Inhalte und Vorteile über eine Saison oder mehrere Venues.', 'Flex-Saisonpass mit wählbaren Spielen; Venue-Pass für Konzerte.', 'Wissensbasis: Flex- und Mitgliedschaftsmodelle in Ligen und bei Venue-Betreibern – zu validieren.', 'Prognose: Planbarkeit von Erlösen gewinnt an Bedeutung.', 'Planbare Erlöse, Datenzugang.', 'Kannibalisierung, Abo-Müdigkeit.', 'C', true, false, 'published'),
  (15, 'Direct-to-Fan-Plattformen', 'C', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Plattformen'), 'GLOBAL', 'Ligen, Clubs und Künstler bauen eigene Kanäle für Content, Commerce und Daten auf.', 'Eigene Streaming- und Community-Plattform; Creator-Kanäle der Spieler.', 'Kings League verbreitet Events über Kanäle von Team-Präsidenten und Partnern [s6].', 'Belegt: Reichweite über eigene und Creator-Kanäle.', 'Eigene Daten, Unabhängigkeit von Intermediären.', 'Reichweitenverlust gegenüber Plattformen.', 'B', false, false, 'published'),
  (16, 'Event-Tourismus-Pakete', 'C', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Hotellerie'), 'GLOBAL', 'Ticket, Hotel, Mobilität und Rahmenprogramm werden als ein Reiseprodukt vermarktet.', 'Matchday-to-Stay-Pakete; Konzertreisen; Turnier-Pakete für internationale Fans.', 'Eras Tour treibt Hotelpreise und -umsätze in Europa [s31, s32]; Women''s EURO 2025 mit 220 Mio. € Effekt für die Schweiz [s26]; Vegas GP [s45].', 'Belegt: messbare Tourismuseffekte von Großevents.', 'Zusatzerlöse, Destinationspartnerschaften.', 'Preis-Backlash, Kapazitätsengpässe.', 'A', false, false, 'published'),
  (17, 'Fan Tokens & Web3', 'C', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Loyalty'), 'GLOBAL', 'Blockchain-basierte Tokens versprechen Mitbestimmung, Prämien und digitale Sammelobjekte.', 'Abstimmungen über Kleinigkeiten, Prämien, Zugang zu Erlebnissen.', 'Socios/Chiliz als größte Plattform; Chiliz wechselt 2026 auf Solana [s96]; Branchenkommentare sehen das Modell kritisch [s95].', 'Belegt: Plattform aktiv. Gegenposition: Zweifel am langfristigen Nutzen.', 'Zusatzerlöse, internationale Fans.', 'Spekulation, Regulierung (MiCA), Reputationsrisiko.', 'B', true, false, 'published'),
  (18, 'Biometrischer Zugang', 'D', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Einlass'), 'US', 'Gesicht als Ticket und Zahlungsmittel für reibungslosen Einlass und Kauf.', 'Opt-in-Gesichtseinlass; Bezahlung ohne Karte; Hotel-Check-in.', 'NFL rollt Gesichtsauthentifizierung ligaweit aus [s19]; LAFC nutzt Wicket für Einlass und Zahlung [s20]; Intuit Dome [s21].', 'Belegt: USA skaliert. Europa: DSGVO verlangt Einwilligung und Folgenabschätzung.', 'Kürzere Wartezeiten, weniger Ticketbetrug.', 'Datenschutz, Akzeptanz, Diskriminierungsrisiken.', 'A', false, false, 'published'),
  (19, 'Checkout-freie Gastronomie', 'D', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Kiosk & Gastro'), 'US', 'Kaufen ohne Kasse per Sensorik oder Scan verkürzt Wartezeiten in Pausen.', 'Walk-out-Kioske im Stadion; Grab-and-go in Arenen und Festivals.', 'Tennessee Titans als erstes NFL-Team mit Just Walk Out (Januar 2026) [s30]; Zippin mit fünf Stores im NRG Stadium [s67].', 'Belegt: Ausbau in US-Venues.', 'Mehr Umsatz pro Kopf, weniger Personalbedarf.', 'Investition, Datenschutz, Diebstahlquote.', 'A', false, false, 'published'),
  (20, 'Multi-Use-Arenen', 'D', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Stadionbau'), 'EU', 'Venues werden ganzjährig für Sport, Konzerte, Training, Breitensport und Firmenevents genutzt.', 'Mehrere Sportarten unter einem Dach; Off-Day-Programmierung mit Community-Formaten.', 'SAP Garden München für Eishockey, Basketball und Breitensport [s22]; Intuit Dome [s47].', 'Belegt: neue Arenen setzen auf Ganzjahresnutzung.', 'Höhere Auslastung, Diversifizierung.', 'Umbauzeiten, Konflikte zwischen Nutzern.', 'A', false, false, 'published'),
  (21, 'Stadion-Quartiere', 'D', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Stadionbau'), 'US', 'Venues werden Kern gemischter Quartiere mit Hotel, Handel, Wohnen und Entertainment.', 'Hotel am Stadion; ganzjährige Gastronomie; Entertainment-Districts.', 'Hollywood Park Inglewood mit Cosm-Venue im Umfeld des SoFi Stadium [s9].', 'Belegt: US-Beispiele. Prognose: in Europa abhängig von Planungsrecht und Kapital.', 'Ganzjährige Erlöse, Immobilienwert.', 'Lange Planungszyklen, Kapitalbedarf.', 'B', false, false, 'published'),
  (22, 'Smart Hotel Rooms', 'D', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Hotellerie'), 'GLOBAL', 'Digitaler Schlüssel, IoT-Steuerung und Sprachassistenten individualisieren das Zimmer.', 'Mobile Key; Raumprofil nach Gastpräferenz; Fan-Zimmer zum Event.', 'Wissensbasis: Mobile Key bei großen Hotelketten verbreitet – zu validieren.', 'Prognose: Verknüpfung mit Loyalty und Agentic Booking.', 'Effizienz, Upselling, Gästezufriedenheit.', 'Technikabhängigkeit, Sicherheitslücken.', 'C', false, false, 'published'),
  (23, 'Private 5G & Wi-Fi 7', 'D', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Stadionbau'), 'GLOBAL', 'Hochleistungsnetze sind Grundlage für Streaming, Zahlungen, Biometrie und Produktion vor Ort.', 'Stabile Fan-Konnektivität; drahtlose TV-Produktion; Sensorik für Digital Twins.', 'Intuit Dome als technologieintensive Arena [s47].', 'Prognose: Konnektivität wird Basisvoraussetzung für alle digitalen Trends.', 'Enabler für Commerce und Daten.', 'Investition, schnelle Technologiezyklen.', 'B', false, false, 'published'),
  (24, 'Mobile Order & In-Seat', 'D', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Kiosk & Gastro'), 'EU', 'Bestellen per App mit Abholung am Express-Schalter oder Lieferung an den Platz.', 'Pausen-Vorbestellung, Lieferung in Premium-Bereiche, Abholfächer.', 'SeatServe an der Anfield Road [s81]; Newcastle United liefert an den Platz [s82].', 'Belegt: Einsatz in der Premier League.', 'Mehr Umsatz pro Kopf, kürzere Schlangen, Daten zu Kaufverhalten.', 'Logistik in vollen Blöcken, Personal für Lieferung.', 'A', false, false, 'published'),
  (25, 'Self-Pour & Smart Schank', 'D', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Schanktechnik'), 'GLOBAL', 'Selbstzapf-Wände, Hochleistungsschank und sensorgesteuertes Zapfen erhöhen Durchsatz und reduzieren Schwund.', 'Bierwände mit Bezahlung per Karte oder Armband, Schnellzapfsysteme für Pausenspitzen.', 'Sodexo Live! mit permanenten Ebar-Beerwalls beim Millwall FC als europäische Premiere [s77]; Draft Picks Perfect Pour im Honda Center ausgezeichnet [s78]; PourMyBeer für Stadien [s80].', 'Belegt: Ausbreitung in UK und USA [s79]. DACH: Altersprüfung und Jugendschutz klären.', 'Höherer Durchsatz, weniger Personal am Hahn, exakte Abrechnung.', 'Jugendschutz, Hygiene, Akzeptanz beim Bierpartner.', 'A', false, false, 'published'),
  (26, 'Cashless & Mobile POS', 'D', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Kiosk & Gastro'), 'EU', 'Offene Kartenzahlung und mobile Terminals ersetzen Bargeld und geschlossene Stadion-Bezahlkarten.', 'Mobile Terminals im Umlauf, Kartenzahlung an allen Kiosken, Zahlung per Smartphone.', 'VfB Stuttgart und LBBW führen mobile Terminals in der MHP Arena ein [s75]; LASK Raiffeisen Arena mit Mastercard und card complete [s100].', 'Belegt: Wechsel weg von geschlossenen Bezahlkarten, die Verbraucherschützer kritisiert haben [s76].', 'Schnellere Abwicklung, kein Restguthaben-Ärger, bessere Daten.', 'Gebühren, Netzausfall, Fans mit Bargeldpräferenz.', 'A', false, false, 'published'),
  (27, 'Digitale Tickets & Anti-Fraud', 'D', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Einlass'), 'EU', 'Personalisierte, digitale Tickets mit kontrollierter Weitergabe gegen Fälschung und Schwarzmarkt.', 'Ticket-Wallet, offizieller Zweitmarkt, Weitergabe an Fanclubs, Einlass per App.', 'FC Bayern ab 2026/27 nur noch digitale Tickets, um Schwarzmarkt und Fälschungen zu verhindern [s74].', 'Belegt: DACH-Vorreiter. Offen: Barrierefreiheit der App, Lösungen für Fans ohne Smartphone.', 'Weniger Betrug, Daten zu realen Besuchern, Zweitmarkterlöse.', 'Ausschluss, technische Ausfälle am Einlass, Fan-Widerstand.', 'A', false, false, 'published'),
  (28, 'Phygitale Fan-Hubs', 'E', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Content & Community'), 'EU', 'Fan-Zonen, Watch-Partys und Hotel-Lounges werden zu vernetzten Erlebnisorten mit Live-Daten und Commerce.', 'Hotelbar als offizieller Watch-Party-Ort; Fan-Zonen mit digitalem Check-in und Merchandising.', 'UEFA Women''s EURO 2025 mit Rekordzahlen und Fan-Aktivierungen in der Schweiz [s25, s26].', 'Belegt: Großevents erzeugen hohe Nachfrage außerhalb des Stadions.', 'Erlöse jenseits der Stadionkapazität, Hotelauslastung.', 'Sicherheit, Lizenzrechte für öffentliche Vorführungen.', 'B', false, false, 'published'),
  (29, 'Competitive Socialising', 'E', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Kiosk & Gastro'), 'EU', 'Gastronomie trifft Spiel: Darts, Mini-Golf und Simulatoren als soziale Erlebnisse.', 'Social-Gaming-Zonen in Arenen und Hotels; Fan-Bars mit Spielangeboten.', 'Savills: schnelles Wachstum des Segments [s36]; Flight Club plant 45 neue Venues [s37]; Marktreife zeichnet sich ab [s38].', 'Belegt: Expansion. Unsicher: Sättigung in Metropolen.', 'Ganzjährige Frequenz in Venue-Umfeld.', 'Sättigung, hoher Flächenbedarf.', 'A', false, false, 'published'),
  (30, 'Gaming-Welten als Bühne', 'E', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Gamification'), 'GLOBAL', 'Plattformen wie Roblox und Fortnite werden Orte für Fan-Erlebnisse, Konzerte und Sponsoring.', 'Virtuelles Stadion; Konzerte in Games; digitale Fanartikel.', 'FIFA baut Roblox-Engagement aus [s39].', 'Belegt: Sportverbände investieren. Prognose: Zugang zu Gen Alpha.', 'Neue Zielgruppen, digitale Güter.', 'Kurzlebigkeit, Kinderschutz.', 'B', false, false, 'published'),
  (31, 'Circular Events', 'F', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Kiosk & Gastro'), 'EU', 'Mehrweg, Kreislauf und Abfallvermeidung werden Standard bei Events und Festivals.', 'Mehrwegbecher, Pfandsysteme, kreislauffähige Bühnenbauten.', 'Tomorrowland 2025 komplett auf Mehrweg mit Smart Cups [s42]; 97 % Rücklaufquote in Dänemark [s43]; Roskilde [s50].', 'Belegt: regulatorischer Druck. Gegenposition: Kritik an Materialwahl [s44].', 'Kosteneinsparung, Sponsor-Aktivierung.', 'Greenwashing-Vorwürfe, Logistik.', 'A', false, true, 'published'),
  (32, 'Green Fan Mobility', 'F', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Mobilität'), 'EU', 'Anreise ist der größte Emissionsposten – ÖPNV-Kombitickets und Shuttles werden Pflichtprogramm.', 'Kombiticket, Fahrrad-Parking, E-Shuttles.', 'DFB/DFL testen digitale Parklösungen [s73]; Kombitickets mit ÖPNV sind in DACH verbreitet (Wissensbasis).', 'Prognose: Berichterstattung über Emissionen erhöht Druck.', 'Weniger Parkflächen, besseres Erlebnis.', 'Kapazität im ÖPNV.', 'B', false, false, 'published'),
  (33, 'Regenerative Hospitality', 'F', 'HOS', (select id from subtopics where focus_code = 'HOS' and name = 'Hotellerie'), 'GLOBAL', 'Hotels und Events wollen positive Effekte für Region und Umwelt erzeugen, nicht nur weniger Schaden.', 'Regionale Lieferketten, Renaturierung, Community-Programme.', 'Keine Primärquelle in dieser Recherche verifiziert.', 'Prognose: Differenzierung im Premium-Segment.', 'Markendifferenzierung, Preisbereitschaft.', 'Messbarkeit, Greenwashing.', 'C', true, false, 'published'),
  (34, 'Energiespeicher & EMS', 'F', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Energie'), 'EU', 'Batteriespeicher und Energiemanagement glätten Lastspitzen an Eventtagen und vermarkten Flexibilität am Strommarkt.', 'Notstrom statt Dieselaggregat, Lastspitzen-Kappung, Netzdienstleistungen an Nicht-Eventtagen.', 'Johan Cruijff ArenA mit 3-MW-Speicher aus wiederverwendeten Nissan-Batterien [s90].', 'Belegt: Referenz seit 2018. Prognose: sinkende Speicherkosten erhöhen Wirtschaftlichkeit.', 'Geringere Energiekosten, Zusatzerlöse, Versorgungssicherheit.', 'Investition, Brandschutz, Netzanschluss.', 'A', false, false, 'published'),
  (35, 'Energiepositive Venues', 'F', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Energie'), 'EU', 'Venues erzeugen mehr Energie als sie verbrauchen und werden Teil lokaler Energiesysteme.', 'PV-Dächer, Batteriespeicher, Wärmenetze.', 'Tottenham Hotspur Stadium als Nachhaltigkeitsbeispiel [s48].', 'Prognose: Energiepreise und Regulierung treiben Investitionen.', 'Kostensenkung, neue Erlöse.', 'Hohe Anfangsinvestition.', 'B', false, false, 'published'),
  (36, 'Holz- & Modularbau', 'F', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Stadionbau'), 'EU', 'Holz und modulare Bauteile senken graue Emissionen und erlauben flexible Erweiterung oder Rückbau.', 'Holz-Tribünen, modulare Ausbaustufen, temporäre Tribünen für Turniere.', 'Forest Green Rovers planen mit Zaha Hadid Architects ein Stadion fast vollständig aus Holz [s91].', 'Belegt: Planungen. Unsicher: Umsetzung und Brandschutz bei Großstadien.', 'Geringere CO2-Bilanz, schnellere Bauzeit, Anpassbarkeit.', 'Genehmigung, Brandschutz, Kostenunsicherheit.', 'B', false, false, 'published'),
  (37, 'KI-Crowd-Management', 'G', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Sicherheit'), 'EU', 'KI prognostiziert Besucherströme für Einlass, Gastronomie und Abreise und steuert proaktiv.', 'Dynamische Einlasszeiten; Personalplanung nach Prognose; Abreise-Lenkung mit ÖPNV.', 'DFB/DFL testen 2025/26 KI-gestütztes Crowd-Management in der Projektgruppe Stadioninnovationen [s73]; Simulationsanbieter wie Simio [s35].', 'Belegt: Piloten in deutschen Stadien. Prognose: Teil der Sicherheits- und Einlassplanung.', 'Weniger Wartezeit, mehr Umsatz pro Kopf, Sicherheit.', 'Datenqualität, Integration in Sicherheitsprozesse.', 'A', false, false, 'published'),
  (38, 'KI-Screening & Videoschutz', 'G', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Sicherheit'), 'US', 'KI-Videoanalyse und berührungsloses Waffen-Screening beschleunigen Einlass und erkennen Gefahren früher.', 'Walk-through-Screening am Einlass, Erkennung von Gedränge oder liegengebliebenen Objekten.', 'Evolv sichert die Club-WM 2025 und europäische Events [s86, s87]; Staige One liefert KI-Videoschutz u. a. für die Polizei Berlin [s85].', 'Belegt: Einsatz bei Großevents. Europa: EU AI Act und DSGVO begrenzen biometrische Auswertung.', 'Schnellerer Einlass, höhere Sicherheit, weniger Personal an Kontrollen.', 'Fehlalarme, Rechtsrahmen, Akzeptanz bei Fanszenen.', 'A', false, false, 'published'),
  (39, 'Drohnenabwehr', 'G', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Sicherheit'), 'GLOBAL', 'Detektion und Abwehr unerlaubter Drohnen über Stadien und Fan-Zonen.', 'Radar-Detektion, Lagebild für Sicherheitsdienst und Polizei, Flugverbotszonen.', 'USA planen 500 Mio. US$ für Drohnensicherheit bei der WM 2026 [s88]; Anbieter wie Robin Radar bieten Stadion-Detektion [s89].', 'Belegt: hoher Aufwand bei Großturnieren. Unsicher: Abwehr ist in Deutschland Sache der Behörden.', 'Schutz vor neuen Gefahren, Versicherbarkeit von Großevents.', 'Rechtslage, Kosten, Zuständigkeiten.', 'A', true, false, 'published'),
  (40, 'Cyber-Resilienz', 'G', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Sicherheit'), 'GLOBAL', 'Vernetzte Venues, Ticketing und Zahlungen werden zum Angriffsziel – Resilienz wird Erlebnisfaktor.', 'Notfallbetrieb für Ticketing und Einlass; Schutz von Fan-Daten.', 'Keine Primärquelle in dieser Recherche verifiziert.', 'Prognose: steigende Abhängigkeit von digitaler Infrastruktur erhöht Risiko.', 'Vertrauen, Ausfallsicherheit, Versicherbarkeit.', 'Betriebsausfall, Datenlecks, Reputationsschäden.', 'C', true, false, 'published'),
  (41, 'Hitzeschutz & Wetterresilienz', 'G', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Sicherheit'), 'GLOBAL', 'Hitze und Unwetter verlangen Kühlzonen, Wetterwarnsysteme und angepasste Abläufe in Venues.', 'Wetterberatung für Spieltage, Trinkwasserstellen, Schattenzonen, Evakuierungspläne bei Gewitter.', 'DFB/DFL testen Wetterberatung zur Zuschauersicherheit [s73]; FIFPRO warnt nach der Club-WM 2025 vor Hitze [s23, s24].', 'Belegt: Spielergewerkschaft fordert Anpassungen.', 'Gesundheit, Planbarkeit, neue Formate.', 'Konflikt mit TV-Slots, Kosten.', 'A', false, false, 'published'),
  (42, 'Barrierefreie Experiences', 'G', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Inklusion'), 'EU', 'Digitale und physische Barrierefreiheit wird Pflicht und Qualitätsmerkmal.', 'Barrierefreie Ticketshops, sensorische Ruheräume, Audiodeskription.', 'European Accessibility Act seit Juni 2025 [s33, s34]; DFB/DFL testen flexible Rollstuhlplatz-Systeme [s73].', 'Belegt: gesetzliche Pflicht.', 'Größere Zielgruppe, Rechtssicherheit.', 'Bußgelder bei Nichterfüllung.', 'A', false, true, 'published'),
  (43, 'Sensory-inklusive Venues', 'G', 'INF', (select id from subtopics where focus_code = 'INF' and name = 'Inklusion'), 'GLOBAL', 'Ruheräume, Sinnes-Karten und geschultes Personal für neurodivergente Besucher.', 'Sensory Rooms mit Blick aufs Spielfeld, Ruhezonen, Lärmschutz-Kits, Vorab-Informationen.', 'WM 2026 als erstes „sensory inclusive“ Turnier ausgezeichnet [s97]; Sensory Rooms in Wembley [s98] und bei Manchester City [s99].', 'Belegt: wachsende Verbreitung in UK und bei Turnieren.', 'Neue Zielgruppen, Familienfreundlichkeit, Reputation.', 'Flächenbedarf, Schulungsaufwand.', 'A', false, false, 'published'),
  (44, 'Faire Preise & Teilhabe', 'G', 'FAN', (select id from subtopics where focus_code = 'FAN' and name = 'Teilhabe'), 'EU', 'Bezahlbare Kontingente, Stehplätze, Preisobergrenzen und Fan-Dialog sichern den Zugang breiter Zielgruppen – als Gegengewicht zu Premiumisierung und dynamischen Preisen.', 'Preisdeckel für Gästetickets, Jugend- und Sozialkontingente, Erhalt von Stehplätzen, Fanbeiräte bei Preisentscheidungen.', 'Premier League verlängert die 30-£-Obergrenze für Auswärtstickets um zwei Spielzeiten [s101, s102]; UEFA senkt Preisobergrenzen für Gästetickets [s104]; Bundesliga meldet Zuschauerrekorde 2025/26 [s103].', 'Belegt: Preisobergrenzen in UK und bei der UEFA. Prognose: Teilhabe wird zur Lizenz- und Reputationsfrage, wenn Premium-Anteile steigen.', 'Fanbindung, Legitimation für Premium-Ausbau, Reputation bei Politik und Sponsoren.', 'Erlösverzicht, Zielkonflikt mit dynamischen Preisen.', 'A', false, false, 'published');
